// Next Monday 00:00 -> next Sunday, as ISO dates.
const now = new Date();
const day = now.getDay();                 // 0=Sun
const daysToNextMon = ((8 - day) % 7) || 7;
const monday = new Date(now);
monday.setDate(now.getDate() + daysToNextMon);
const sunday = new Date(monday);
sunday.setDate(monday.getDate() + 6);

// fairness lookback
const histStart = new Date(now);
histStart.setDate(now.getDate() - 28);

const iso = (d) => d.toISOString().slice(0, 10);

return [{ json: {
  weekStart: iso(monday),
  weekEnd: iso(sunday),
  historyStart: iso(histStart),
  historyEnd: iso(now),
}}];

// Reshape five Airtable result sets into the engine's input contract.
// The Airtable node returns either { id, fields:{...} } or a flattened
// { id, ...fieldValues } depending on node version. Normalise both shapes.
const REC = (j) => (j && j.fields) ? j : { id: j && j.id, fields: j || {} };
const rows = (n) => { try { return $(n).all().map(i => REC(i.json)).filter(r => r && r.id); } catch (e) { return []; } };
const one  = (v) => Array.isArray(v) ? v[0] : v;

return [{ json: {
  sessions: rows('Get Sessions').map(r => ({
    id: r.id,
    date: r.fields['Date'],
    startTime: r.fields['Start Time'],
    endTime: r.fields['End Time'],
    clientId: one(r.fields['Client']),
    clientName: one(r.fields['Client Name']) || 'Unknown',
    clientTier: one(r.fields['Brand Tier']) || 'C',
    requiresCertification: Boolean(one(r.fields['Requires Certification'])),
    hostsRequired: r.fields['Hosts Required'] || 0,
    adminsRequired: r.fields['Admins Required'] || 0,
  })),
  staff: rows('Get Staff').map(r => ({
    id: r.id,
    name: r.fields['Name'],
    role: r.fields['Role'],
    active: Boolean(r.fields['Active']),
    certifiedClients: r.fields['Certified Clients'] || [],
    maxSessionsPerWeek: r.fields['Max Sessions Per Week'] || 99,
    notifyChannel: r.fields['Notify Channel'] || 'Email',
  })),
  availability: rows('Get Availability').map(r => ({
    staffId: one(r.fields['Staff']),
    date: r.fields['Date'],
    availableFrom: r.fields['Available From'],
    availableTo: r.fields['Available To'],
  })),
  absences: rows('Get Absences').map(r => ({
    staffId: one(r.fields['Staff']),
    date: r.fields['Date'],
    startTime: r.fields['Start Time'],
    endTime: r.fields['End Time'],
  })),
  history: rows('Get History (28d)').map(r => ({
    staffId: one(r.fields['Staff']),
    date: one(r.fields['Session Date']),
    startTime: one(r.fields['Session Start']),
    endTime: one(r.fields['Session End']),
    weight: r.fields['Weight'] || 1,
  })),
}}];

// ============================================================
// KLAIYA SCHEDULING ENGINE - deterministic assignment
// Mode: Run Once for All Items
// ============================================================
const input        = $input.first().json;
const sessions     = input.sessions     || [];
const staff        = input.staff        || [];
const availability = input.availability || [];
const absences     = input.absences     || [];
const history      = input.history      || [];

const CONFIG = {
  primeStart: '18:00',
  primeEnd: '22:00',
  primeMultiplier: 1.5,
  tierMultiplier: { A: 1.4, B: 1.2, C: 1.0 },
  bufferMinutes: 30,
};

const toMin = (t) => {
  const [h, m] = String(t || '0:0').split(':').map(Number);
  return (h * 60) + m;
};
const overlaps = (aS, aE, bS, bE, buf = 0) =>
  toMin(aS) < toMin(bE) + buf && toMin(bS) < toMin(aE) + buf;
const contains = (oS, oE, iS, iE) =>
  toMin(oS) <= toMin(iS) && toMin(oE) >= toMin(iE);
const daysBetween = (a, b) => Math.round((new Date(a) - new Date(b)) / 86400000);
const stableHash = (s) => {
  let h = 0;
  const str = String(s);
  for (let i = 0; i < str.length; i++) h = ((h << 5) - h + str.charCodeAt(i)) | 0;
  return Math.abs(h);
};

const sessionWeight = (s) => {
  const prime = toMin(s.startTime) >= toMin(CONFIG.primeStart)
             && toMin(s.startTime) <  toMin(CONFIG.primeEnd);
  return 1.0 * (prime ? CONFIG.primeMultiplier : 1.0)
             * (CONFIG.tierMultiplier[s.clientTier || 'C'] || 1.0);
};

const availByStaff = {}, absenceByStaff = {}, historyByStaff = {};
for (const a of availability) (availByStaff[a.staffId] = availByStaff[a.staffId] || []).push(a);
for (const a of absences)     (absenceByStaff[a.staffId] = absenceByStaff[a.staffId] || []).push(a);
for (const h of history)      (historyByStaff[h.staffId] = historyByStaff[h.staffId] || []).push(h);

const ledger = {};
for (const s of staff) {
  const hist = historyByStaff[s.id] || [];
  ledger[s.id] = {
    weightedLoad: hist.reduce((sum, h) => sum + (Number(h.weight) || 1), 0),
    availableCount: (availByStaff[s.id] || []).length,
    weekCount: 0,
    lastShiftDate: hist.length ? hist.map(h => h.date).filter(Boolean).sort().slice(-1)[0] : null,
    booked: hist.map(h => ({ date: h.date, start: h.startTime, end: h.endTime })),
  };
}

const fairnessScore = (sid) => {
  const L = ledger[sid];
  return (L.weightedLoad + 1) / (L.availableCount + 1);
};

// returns null if eligible, else a reason string
const isEligible = (p, session, role) => {
  if (!p.active) return 'inactive';
  if (p.role !== role && p.role !== 'Both') return 'role';
  if (session.requiresCertification && !(p.certifiedClients || []).includes(session.clientId))
    return 'not-certified';

  const avail = (availByStaff[p.id] || []).filter(a => a.date === session.date);
  if (!avail.some(a => contains(a.availableFrom, a.availableTo, session.startTime, session.endTime)))
    return 'unavailable';

  if ((absenceByStaff[p.id] || []).some(a => a.date === session.date &&
      overlaps(a.startTime || '00:00', a.endTime || '23:59', session.startTime, session.endTime)))
    return 'absent';

  if (ledger[p.id].booked.some(b => b.date === session.date &&
      overlaps(b.start, b.end, session.startTime, session.endTime, CONFIG.bufferMinutes)))
    return 'conflict';

  if (ledger[p.id].weekCount >= (p.maxSessionsPerWeek || 99)) return 'at-cap';
  return null;
};

const eligibleFor = (session, role, exclude = []) =>
  staff.filter(p => !exclude.includes(p.id) && isEligible(p, session, role) === null);

// build slot list
const slots = [];
for (const s of sessions) {
  for (let i = 0; i < (s.hostsRequired  || 0); i++) slots.push({ session: s, role: 'Live Host' });
  for (let i = 0; i < (s.adminsRequired || 0); i++) slots.push({ session: s, role: 'Live Admin' });
}

// SCARCITY FIRST - hardest-to-fill slots get first pick of the pool
slots.sort((a, b) =>
  eligibleFor(a.session, a.role).length - eligibleFor(b.session, b.role).length);

const assignments = [], gaps = [], perSession = {};
let conflictsPrevented = 0;

for (const slot of slots) {
  const { session, role } = slot;
  const already = perSession[session.id] || [];

  // count how many people were blocked purely by a time conflict - this is the
  // "double-booking prevented" number for the before/after slide
  conflictsPrevented += staff.filter(p =>
    !already.includes(p.id) && isEligible(p, session, role) === 'conflict').length;

  const candidates = eligibleFor(session, role, already);

  if (candidates.length === 0) {
    const reasons = {};
    for (const p of staff) {
      const r = isEligible(p, session, role);
      if (r) reasons[r] = (reasons[r] || 0) + 1;
    }
    gaps.push({
      sessionId: session.id,
      date: session.date,
      startTime: session.startTime,
      endTime: session.endTime,
      client: session.clientName,
      role,
      reasonBreakdown: reasons,
    });
    continue;
  }

  candidates.sort((a, b) => {
    const fa = fairnessScore(a.id), fb = fairnessScore(b.id);
    if (fa !== fb) return fa - fb;
    const da = ledger[a.id].lastShiftDate ? daysBetween(session.date, ledger[a.id].lastShiftDate) : 9999;
    const db = ledger[b.id].lastShiftDate ? daysBetween(session.date, ledger[b.id].lastShiftDate) : 9999;
    if (da !== db) return db - da;
    return stableHash(a.id) - stableHash(b.id);
  });

  const chosen = candidates[0];
  const weight = sessionWeight(session);

  assignments.push({
    sessionId: session.id,
    staffId: chosen.id,
    staffName: chosen.name,
    role, weight,
    date: session.date,
    startTime: session.startTime,
    endTime: session.endTime,
    client: session.clientName,
    fairnessScoreAtAssignment: Number(fairnessScore(chosen.id).toFixed(3)),
  });

  const L = ledger[chosen.id];
  L.weightedLoad += weight;
  L.weekCount += 1;
  L.lastShiftDate = session.date;
  L.booked.push({ date: session.date, start: session.startTime, end: session.endTime });
  (perSession[session.id] = perSession[session.id] || []).push(chosen.id);
}

const loads = staff.filter(s => s.active).map(s => ledger[s.id].weightedLoad);
const mean = loads.reduce((a, b) => a + b, 0) / (loads.length || 1);
const stdev = Math.sqrt(loads.reduce((s, l) => s + Math.pow(l - mean, 2), 0) / (loads.length || 1));

return [{ json: {
  assignments, gaps,
  stats: {
    slotsTotal: slots.length,
    slotsFilled: assignments.length,
    slotsUnfilled: gaps.length,
    coveragePct: slots.length ? Number(((assignments.length / slots.length) * 100).toFixed(1)) : 100,
    conflictsPrevented,
    loadMean: Number(mean.toFixed(2)),
    loadStdev: Number(stdev.toFixed(2)),
    staffCount: staff.filter(s => s.active).length,
    generatedAt: new Date().toISOString(),
  },
}}];

// One item per assignment, keys = exact Airtable field names
// so the Airtable node can auto-map input data.
const { assignments } = $input.first().json;
return assignments.map(a => ({ json: {
  'Session': [a.sessionId],
  'Staff': [a.staffId],
  'Role': a.role,
  'Status': 'Draft',
  'Assigned By': 'Auto',
  'Approved': false,
  'Notified': false,
  'Weight': a.weight,
  'Fairness Score At Assignment': a.fairnessScoreAtAssignment,
}}));

// Groq node runs with onError=continueRegularOutput, so check for a usable body.
const r = $input.first().json;
const engine = $('Assignment Engine').first().json;
const s = engine.stats;

let summary;
if (r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) {
  summary = r.choices[0].message.content;
} else {
  // static fallback - never block on a Groq failure
  summary = engine.gaps.map(g =>
    `- ${g.client} ${g.date} ${g.startTime}-${g.endTime}: no ${g.role} available`
  ).join('\n');
}

const text = [
  '<b>Draft schedule ready for review</b>',
  `Coverage: ${s.slotsFilled}/${s.slotsTotal} slots (${s.coveragePct}%)`,
  `Double-bookings prevented: ${s.conflictsPrevented}`,
  `Load spread (stdev): ${s.loadStdev} across ${s.staffCount} staff`,
  '',
  `<b>${engine.gaps.length} gap(s) need attention:</b>`,
  summary,
  '',
  'Review and tick Approved in the Scheduler Review view. Nothing is sent to staff until you do.',
].join('\n');

return [{ json: { text, source: (r && r.choices) ? 'groq' : 'fallback' } }];

const s = $('Assignment Engine').first().json.stats;
return [{ json: { text: [
  '<b>Draft schedule ready for review</b>',
  `Coverage: ${s.slotsFilled}/${s.slotsTotal} slots (100%) - no gaps.`,
  `Double-bookings prevented: ${s.conflictsPrevented}`,
  `Load spread (stdev): ${s.loadStdev} across ${s.staffCount} staff`,
  '',
  'Review and tick Approved in the Scheduler Review view.',
].join('\n') }}];

const s = $('Assignment Engine').first().json.stats;
return [{ json: {
  'Action': 'DRAFT_GENERATED',
  'Actor': 'Workflow A',
  'Source': 'Automated',
  'After Value': JSON.stringify(s),
  'Reason': `Weekly draft for ${$('Compute Week Window').first().json.weekStart} to ${$('Compute Week Window').first().json.weekEnd}`,
}}];
